from html.parser import HTMLParser
from urllib.parse import urldefrag, urljoin, urlparse


class _GuideParser(HTMLParser):
    def __init__(self, base_url):
        super().__init__(convert_charrefs=True)
        self.base_url = base_url
        self.guide_depth = 0
        self.article_stack = []
        self.links = []
        self.seen = set()

    def handle_starttag(self, tag, attrs):
        attributes = dict(attrs)
        if tag == "article":
            qualified = attributes.get("data-kind") == "guide"
            self.article_stack.append(qualified)
            if qualified:
                self.guide_depth += 1
        elif tag == "a" and self.guide_depth:
            href = attributes.get("href")
            if not href:
                return
            resolved, _ = urldefrag(urljoin(self.base_url, href))
            parsed = urlparse(resolved)
            if parsed.scheme in ("http", "https") and parsed.netloc:
                self.seen.add(resolved)
                self.links.append(resolved)

    def handle_endtag(self, tag):
        if tag == "article" and self.article_stack:
            if self.article_stack.pop():
                self.guide_depth -= 1


def extract_guide_links(html, base_url):
    if not isinstance(html, str) or not isinstance(base_url, str):
        raise TypeError("html and base_url must be strings")
    parsed = urlparse(base_url)
    if parsed.scheme not in ("http", "https") or not parsed.netloc:
        raise ValueError("base_url must be an absolute HTTP URL")
    parser = _GuideParser(base_url)
    parser.feed(html)
    parser.close()
    return list(parser.links)

